const fs = require('node:fs')
const vm = require('node:vm')
const { join } = require('node:path')
const assert = require('node:assert/strict')
const source = fs.readFileSync('scripts/ui-gate/flows/chat-retry-report.mjs', 'utf8')
const start = source.indexOf('  async function checkAssistantParagraphs(turn) {')
const end = source.indexOf('  const composer =', start)
assert(start >= 0 && end > start)
const helper = source.slice(start, end)
const runDir = fs.mkdtempSync('/tmp/CI.63-counterproof-')
fs.writeFileSync(join(runDir, 'dashboard.log'), 'unrelated\n[chat-turn] synthetic counterproof\n')
const paragraph = 'Párrafo sintético de más de cuarenta caracteres para comprobar el rechazo del duplicado.'
const forcedText = `${paragraph}\n\n${paragraph}`
const steps = []
const context = {
  page: { locator: (selector) => {
    assert.equal(selector, 'div.prose')
    return { last: () => ({ innerText: async () => forcedText, innerHTML: async () => '<p>synthetic counterproof</p>' }) }
  } },
  api: async (url, options) => {
    assert.equal(url, '/api/chat/sessions/synthetic-session/messages')
    assert.equal(options.headers['x-orchestos-project-id'], 'synthetic-project')
    return { status: 200, ok: true, data: [{ role: 'assistant', content: forcedText }] }
  },
  session: { id: 'synthetic-session' }, project: { id: 'synthetic-project' },
  step: async (name, ok, detail) => { steps.push({ name, ok, detail }); console.log(JSON.stringify(steps.at(-1))); return ok },
  join, runDir, writeFileSync: fs.writeFileSync, readFileSync: fs.readFileSync,
}
;(async () => {
  await vm.runInNewContext(`${helper}\ncheckAssistantParagraphs(1)`, context)
  assert.equal(steps.length, 1)
  assert.equal(steps[0].ok, false)
  const evidencePath = join(runDir, 'assistant-duplicate-paragraph-turn1.json')
  const evidence = JSON.parse(fs.readFileSync(evidencePath, 'utf8'))
  assert.equal(evidence.duplicates.length, 1)
  assert.equal(evidence.text, forcedText)
  assert.equal(evidence.messages.data[0].content, forcedText)
  assert.deepEqual(evidence.chatTurnLines, ['[chat-turn] synthetic counterproof'])
  console.log('EVIDENCE ' + evidencePath)
  console.log(JSON.stringify(evidence, null, 2))
  console.log('PASS: helper real extraído; lectura forzada temporal; step=false y JSON escrito. Sin modificar el repositorio.')
})().catch((error) => { console.error(error); process.exitCode = 1 })

